const base = {generator:1, storage:2, farm:3, residence:4, cameras:5, security:6};
let depth = 0;
let total = 0;
for (const token of readline().split(' ')) {
    if (token === '(')
        depth++;
    else if (token === ')')
        depth--;
    else
        total += base[token] * (2 ** depth);
}
console.log(total);
